import java.util.Locale;

public class Solution {
    static String initials(String fullName) {
        StringBuilder sb = new StringBuilder();
        for (String name : fullName.trim().split("\\s+")) {
            if (!name.isEmpty()) sb.append(Character.toUpperCase(name.charAt(0))).append('.');
        }
        return sb.toString();
    }

    static int countWord(String text, String word) {
        int count = 0;
        for (String w : text.split("[^\\p{L}]+")) {
            if (w.equalsIgnoreCase(word)) count++;
        }
        return count;
    }

    static String censor(String text, String word) {
        if (word.isEmpty()) return text;
        String lowerText = text.toLowerCase(), lowerWord = word.toLowerCase();
        StringBuilder sb = new StringBuilder(text);
        int at = lowerText.indexOf(lowerWord);
        while (at >= 0) {
            for (int i = at; i < at + word.length(); i++) sb.setCharAt(i, '*');
            at = lowerText.indexOf(lowerWord, at + word.length());
        }
        return sb.toString();
    }

    static String priceLine(String item, double price) {
        return String.format(Locale.ROOT, "%-12s%8.2f", item, price);
    }
}

unitTests:
test("initials", () -> {
    checkEq(Solution.initials("ada king lovelace"), "A.K.L.");
    checkEq(Solution.initials("  Grace   Hopper "), "G.H.");
    checkEq(Solution.initials(""), "");
});

test("counting words", () -> {
    checkEq(Solution.countWord("The cat and the hat. THE end", "the"), 3);
    checkEq(Solution.countWord("theme, then: other", "the"), 0);
    checkEq(Solution.countWord("", "x"), 0);
});

test("censoring", () -> {
    checkEq(Solution.censor("Darn, DARN it", "darn"), "****, **** it");
    checkEq(Solution.censor("darned darn", "DARN"), "****ed ****");
    checkEq(Solution.censor("nothing here", "darn"), "nothing here");
});

test("price lines", () -> {
    checkEq(Solution.priceLine("Tea", 2.5), "Tea             2.50");
    checkEq(Solution.priceLine("Chocolate cake", 12.345), "Chocolate cake   12.35");
    checkEq(Solution.priceLine("Pen", 1234.5).length(), 20);
});

